#include <stack>
#include <string>
using namespace std;
int main() {
  string s = "{[()]}(";
  stack<char> st;
  bool ok = true;
  for (int i = 0; i < s.size(); i++) {
    char c = s[i];
    if (c == '(' || c == '[' || c == '{') st.push(c);
    else {
      if (st.empty()) { ok = false; break; }
      char t = st.top();
      st.pop();
      if ((c == ')' && t != '(') || (c == ']' && t != '[') || (c == '}' && t != '{')) { ok = false; break; }
    }
  }
  if (!st.empty()) ok = false;
  cout << (ok ? "balanced" : "not balanced") << endl;
  return 0;
}
