int main() {
  stack<int> s;
  string e = "23*54*+9-";
  for (int i = 0; i < e.size(); i++) {
    char c = e[i];
    if (c >= '0' && c <= '9') s.push(c - '0');
    else {
      int b = s.top(); s.pop();
      int a = s.top(); s.pop();
      if (c == '+') s.push(a + b);
      else if (c == '-') s.push(a - b);
      else s.push(a * b);
    }
  }
  cout << s.top() << endl;
  return 0;
}
